13	// Interfaces and enums for the CoderAgent protocol.
14	
15	export enum CoderAgentEvent {
16	  /**
17	   * An event requesting one or more tool call confirmations.
18	   */
19	  ToolCallConfirmationEvent = 'tool-call-confirmation',
20	  /**
21	   * An event updating on the status of one or more tool calls.
22	   */
23	  ToolCallUpdateEvent = 'tool-call-update',
24	  /**
25	   * An event providing text updates on the task.
26	   */
27	  TextContentEvent = 'text-content',
28	  /**
29	   * An event that indicates a change in the task's execution state.
30	   */
31	  StateChangeEvent = 'state-change',
32	  /**
33	   * An user-sent event to initiate the agent.
34	   */
35	  StateAgentSettingsEvent = 'agent-settings',
36	  /**
37	   * An event that contains a thought from the agent.
38	   */
39	  ThoughtEvent = 'thought',
40	  /**
41	   * An event that contains citation from the agent.
42	   */
43	  CitationEvent = 'citation',
44	}
45	
46	export interface AgentSettings {
47	  kind: CoderAgentEvent.StateAgentSettingsEvent;
48	  workspacePath: string;
49	  autoExecute?: boolean;
50	}
51	
52	export interface ToolCallConfirmation {
53	  kind: CoderAgentEvent.ToolCallConfirmationEvent;
54	}
55	
56	export interface ToolCallUpdate {
57	  kind: CoderAgentEvent.ToolCallUpdateEvent;
58	}
59	
60	export interface TextContent {
61	  kind: CoderAgentEvent.TextContentEvent;
62	}
63	
64	export interface StateChange {
65	  kind: CoderAgentEvent.StateChangeEvent;
66	}
67	
68	export interface Thought {
69	  kind: CoderAgentEvent.ThoughtEvent;
70	}
71	
72	export interface Citation {
73	  kind: CoderAgentEvent.CitationEvent;
74	}
75	
76	export type ThoughtSummary = {
77	  subject: string;
78	  description: string;
79	};
80	
81	export interface ToolConfirmationResponse {
82	  outcome: ToolConfirmationOutcome;
83	  callId: string;
84	}
85	
86	export type CoderAgentMessage =
87	  | AgentSettings
88	  | ToolCallConfirmation
89	  | ToolCallUpdate
90	  | TextContent
91	  | StateChange
92	  | Thought
93	  | Citation;
94	
95	export interface TaskMetadata {
96	  id: string;
97	  contextId: string;
98	  taskState: TaskState;
99	  model: string;
100	  mcpServers: Array<{
101	    name: string;
102	    status: MCPServerStatus;
103	    tools: Array<{
104	      name: string;
105	      description: string;
106	      parameterSchema: unknown;
107	    }>;
108	  }>;
109	  availableTools: Array<{
110	    name: string;
111	    description: string;
112	    parameterSchema: unknown;
113	  }>;
114	}
115	
116	export interface PersistedStateMetadata {
117	  _agentSettings: AgentSettings;
118	  _taskState: TaskState;
119	}
120	
121	export type PersistedTaskMetadata = { [k: string]: unknown };
122	
123	export const METADATA_KEY = '__persistedState';
124	
125	function isAgentSettings(value: unknown): value is AgentSettings {
126	  return (
127	    typeof value === 'object' &&
128	    value !== null &&
129	    'kind' in value &&
130	    value.kind === CoderAgentEvent.StateAgentSettingsEvent &&
131	    'workspacePath' in value &&
132	    typeof value.workspacePath === 'string'
133	  );
134	}
135	
136	function isPersistedStateMetadata(
137	  value: unknown,
138	): value is PersistedStateMetadata {
139	  return (
140	    typeof value === 'object' &&
141	    value !== null &&
142	    '_agentSettings' in value &&
143	    '_taskState' in value &&
144	    isAgentSettings(value._agentSettings)
145	  );
146	}
147	
148	export function getPersistedState(
149	  metadata: PersistedTaskMetadata,
150	): PersistedStateMetadata | undefined {
151	  const state = metadata?.[METADATA_KEY];
152	  if (isPersistedStateMetadata(state)) {
153	    return state;
154	  }
155	  return undefined;
156	}
157	
158	export function getContextIdFromMetadata(
159	  metadata: PersistedTaskMetadata | undefined,
160	): string | undefined {
161	  if (!metadata) {
162	    return undefined;
163	  }
164	  const contextId = metadata['_contextId'];
165	  return typeof contextId === 'string' ? contextId : undefined;
166	}
167	
168	export function getAgentSettingsFromMetadata(
169	  metadata: PersistedTaskMetadata | undefined,
170	): AgentSettings | undefined {
171	  if (!metadata) {
172	    return undefined;
173	  }
174	  const coderAgent = metadata['coderAgent'];
175	  if (isAgentSettings(coderAgent)) {
176	    return coderAgent;
177	  }
178	  return undefined;
179	}
180	
181	export function setPersistedState(
182	  metadata: PersistedTaskMetadata,
183	  state: PersistedStateMetadata,
184	): PersistedTaskMetadata {
185	  return {
186	    ...metadata,
187	    [METADATA_KEY]: state,
188	  };
189	}
