export interface BaseAgentEvent {
  /** Unique identifier for this event within the session. */
  id: string;
  /** Identifier of the stream this event belongs to. */
  streamId: string;
}

/**
 * Emitted once at the beginning of a stream.
 */
export interface StreamStartEvent extends BaseAgentEvent {
  type: 'stream_start';
}

/**
 * Emitted once at the end of a stream.
 */
export interface StreamEndEvent extends BaseAgentEvent {
  type: 'stream_end';
  reason?: StreamEndReason;
}

/**
 * A conversational message from a participant in the session.
 */
export interface MessageEvent extends BaseAgentEvent {
  type: 'message';
  role: MessageRole;
  content?: unknown;
}

/**
 * A change to one or more session properties.
 */
export interface SessionUpdateEvent extends BaseAgentEvent {
  type: 'session_update';
  update?: Record<string, unknown>;
}

/**
 * The response to a previously issued elicitation.
 */
export interface ElicitationResponseEvent extends BaseAgentEvent {
  type: 'elicitation_response';
  elicitationId?: string;
  response?: unknown;
}

/**
 * The union of all events a {@link AgentSession} can produce.
 */
export type AgentEvent =
  | StreamStartEvent
  | StreamEndEvent
  | MessageEvent
  | SessionUpdateEvent
  | ElicitationResponseEvent;

/**
 * The discriminating `type` of an {@link AgentEvent}.
 */
export type AgentEventType = AgentEvent['type'];

/**
 * Sends a message into the session.
 */
export interface SendMessage {
  type: 'message';
  content?: unknown;
  role?: MessageRole;
  [key: string]: unknown;
}

/**
 * Applies an update to the session's properties.
 */
export interface SendUpdate {
  type: 'update';
  update?: Record<string, unknown>;
  [key: string]: unknown;
}

/**
 * A single elicitation response entry supplied to {@link SendElicitations}.
 */
export interface ElicitationEntry {
  id?: string;
  response?: unknown;
  [key: string]: unknown;
}

/**
 * Responds to one or more pending elicitations.
 */
export interface SendElicitations {
  type: 'elicitations';
  elicitations: ElicitationEntry[];
  [key: string]: unknown;
